CREATE TABLE IF NOT EXISTS paciente(id UUID PRIMARY KEY,tipo_documento VARCHAR(10) NOT NULL,numero_documento VARCHAR(30) NOT NULL,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,fecha_nacimiento DATE NOT NULL,telefono VARCHAR(30) NOT NULL,correo VARCHAR(150) NOT NULL,direccion VARCHAR(250),fecha_registro TIMESTAMP WITH TIME ZONE NOT NULL,estado VARCHAR(10) NOT NULL CHECK(estado IN ('ACTIVO','INACTIVO')),UNIQUE(tipo_documento,numero_documento));
